/**
 * One stored file (blob) of a workspace.
 */
export type StorageFile = {
    byte_size: number;
    /**
     * For `DELETE /api/v1/workspaces/{workspace_id}/storage/files/{file_id}`.
     */
    id: string;
    /**
     * `null` when the file is only used in private places, or no longer used (it stops counting soon).
     */
    name?: string | null;
    /**
     * Where the file is attached; empty when nothing uses it any more.
     */
    uses: Array<StorageFileUse>;
};

export type StorageFileUse = {
    kind: StorageFileUseKind;
    /**
     * The task title, page title or channel name; `null` for emoji, stickers and private places.
     */
    title?: string | null;
};

export type StorageFileUseKind = 'task' | 'page' | 'channel' | 'emoji' | 'sticker' | 'private';

export type StorageOptionsBody = {
    /**
     * New attachment files go to the bucket and existing ones move there. Off: they move back to this server.
     */
    attachments_in_s3: boolean;
    backup_schedule: BackupSchedule;
    /**
     * New backups are uploaded to the bucket.
     */
    backups_in_s3: boolean;
};

export type StorageView = {
    /**
     * New attachment files go to the bucket; existing ones move there in the background.
     */
    attachments_in_s3: boolean;
    backup_schedule: BackupSchedule;
    /**
     * New backups are uploaded to the bucket instead of kept on this server.
     */
    backups_in_s3: boolean;
    /**
     * Attachment files still waiting to move between this server's disk and the bucket.
     */
    files_to_move: number;
    image_compression?: null | CompressionStatus;
    /**
     * Why moving files stopped last time. Orbit retries every ten minutes.
     */
    move_error?: string | null;
    s3?: null | S3View;
};

/**
 * How a view shows sub-issues. `nested` and `flat` only change the client; `hidden` lists
 * top-level tasks only (`POST /tasks/query` `sub_issues`).
 */
export type SubIssuesDisplay = 'nested' | 'flat' | 'hidden';

/**
 * A Stripe subscription status (`subscription.status`).
 */
export type SubscriptionStatus = 'incomplete' | 'incomplete_expired' | 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid' | 'paused';

export type SuspensionBody = {
    suspended: boolean;
};

/**
 * `POST /tasks/bulk`: the updated tasks (no further pages) plus the automation's changes.
 */
export type TaskBulkResponse = {
    auto_closed: Array<AutoClosed>;
    items: Array<TaskRecord>;
    next_cursor?: string | null;
};

export type TaskConflict = {
    current?: unknown;
    current_version?: number | null;
    field?: string | null;
    refresh?: string | null;
};

export type TaskProblem = {
    code: string;
    conflict?: null | TaskConflict;
    detail: string;
    instance: string;
    /**
     * JSON path of the first invalid filter node, e.g. `filter.children[2].value`. Only set
     * for `invalid_filter`.
     */
    path?: string | null;
    request_id: string;
    status: number;
    title: string;
    type: string;
};

export type TaskProperty = 'id' | 'status' | 'assignee' | 'priority' | 'project' | 'due_date' | 'labels' | 'created' | 'updated' | 'sub_issue_progress';

export type TaskQueryBody = {
    cursor?: string | null;
    /**
     * The complete filter tree, including any preset and project scope.
     */
    filter: FilterGroup;
    /**
     * Page size, 1–100 (default 50).
     */
    limit?: number | null;
    order_by: OrderBy;
    /**
     * Ignored when `order_by` is `manual`.
     */
    order_direction: OrderDirection;
    /**
     * Only direct children of this task.
     */
    parent_task_id?: string | null;
    show_completed: ShowCompleted;
    /**
     * The view's sub-issue display; `hidden` returns top-level tasks only (default `nested`).
     */
    sub_issues?: SubIssuesDisplay;
};

export type TaskRecord = {
    /**
     * `GET /tasks/{id}` only: visible ancestors, root first.
     */
    ancestors?: Array<TaskRef> | null;
    assignee_ids: Array<string>;
    /**
     * True while at least one live task that is not completed, cancelled or a duplicate blocks it.
     */
    blocked: boolean;
    /**
     * Epoch of the description's co-editing document (`/tasks/{id}/collab?epoch=`).
     */
    collab_epoch: string;
    created_at: string;
    creator_id?: string | null;
    creator_service_account_id?: string | null;
    creator_service_account_name?: string | null;
    deleted_at?: string | null;
    /**
     * Markdown copy of `description_json` (search, MCP, GitHub, API clients).
     */
    description: string;
    /**
     * BlockNote blocks, the description's source; null for a task written before rich text
     * (only `description` exists then) and in task lists (read the task for it).
     */
    description_json: Array<{
        [key: string]: unknown;
    }> | null;
    due_at?: string | null;
    due_start_at?: string | null;
    duplicate_of: null | TaskRef;
    id: string;
    label_ids: Array<string>;
    /**
     * Per-project sequence number: the task's identifier is `{project key}-{number}`, e.g.
     * `ENG-12`. Reassigned when the task moves to another project; never reused.
     */
    number: number;
    parent: null | TaskRef;
    /**
     * The direct parent; null for top-level tasks.
     */
    parent_task_id: string | null;
    position: number;
    priority: string;
    project_id: string;
    source_url?: string | null;
    status_id: string;
    /**
     * Direct live children in a completed, cancelled or duplicate status.
     */
    sub_issue_closed_count: number;
    /**
     * Direct live children (sub-issues).
     */
    sub_issue_count: number;
    title: string;
    /**
     * Task trash only: descendants trashed together with this task (restored with it).
     */
    trashed_descendant_count?: number | null;
    updated_at: string;
    version: number;
    workspace_id: string;
};

/**
 * A task reference small enough to embed; clients build the display identifier
 * (`{project_key}-{number}`) themselves.
 */
export type TaskRef = {
    id: string;
    /**
     * The task's number in that project.
     */
    number: number;
    project_id: string;
    /**
     * The key of the task's (live) project, e.g. `ORB`.
     */
    project_key: string;
    title: string;
};

export type TaskRelationBody = {
    task_id: string;
    type: NewTaskRelationType;
};

export type TaskRelationDirection = 'outgoing' | 'incoming';

export type TaskRelationRecord = {
    created_at: string;
    /**
     * Outgoing when the viewed task is the relation's source (the blocker or the duplicate).
     */
    direction: TaskRelationDirection;
    id: string;
    task: RelatedTask;
    type: TaskRelationType;
};

export type TaskRelationType = 'blocks' | 'related' | 'duplicate';

export type TaskUpdateBody = {
    assignee_ids?: Array<string> | null;
    /**
     * Markdown. Send `description_json` instead for rich text (not both).
     */
    description?: string | null;
    /**
     * The description as BlockNote blocks; its markdown copy becomes `description`.
     */
    description_json?: Array<{
        [key: string]: unknown;
    }> | null;
    due_at?: string | null;
    due_start_at?: string | null;
    /**
     * Absent: unchanged. A task id: mark this task as a duplicate of it. `null`: unmark.
     */
    duplicate_of_id?: string | null;
    expected_version: number;
    label_ids?: Array<string> | null;
    /**
     * Absent: unchanged. A task id: make this task its sub-issue. `null`: detach.
     */
    parent_task_id?: string | null;
    position?: number | null;
    priority?: string | null;
    project_id?: string | null;
    source_url?: string | null;
    status_id?: string | null;
    title?: string | null;
};

/**
 * `POST /tasks` and `PATCH /tasks/{id}`: the task plus the tasks the sub-issue automation
 * changed.
 */
export type TaskUpdateResponse = TaskRecord & {
    auto_closed: Array<AutoClosed>;
};

